insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('como-se-mueve-la-gente-en-tu-barrio','ciudades',array['sociedad']::text[],'¿Cómo se mueve la gente en tu barrio?','Descubre con encuestas breves y observación cómo se traslada la gente de tu barrio, a pie, en bus, en moto o en auto, adónde va y cuánto tarda.','Investigación','~18 h',18,array['Movilidad','Barrio']::text[],array['investigar']::text[],'propios',NULL,'geografia ingenieria civil sociologia arquitectura estadistica ingenieria industrial economia trabajo social diseno de encuestas. estadistica descriptiva. lectura de datos de movilidad. comunicacion de resultados. un formulario anonimo. hoja de calculo. un mapa en linea.',$a1sld${"id": "como-se-mueve-la-gente-en-tu-barrio", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Cómo se mueve la gente en tu barrio?", "resumen": "Descubre con encuestas breves y observación cómo se traslada la gente de tu barrio, a pie, en bus, en moto o en auto, adónde va y cuánto tarda.", "tipo": "Investigación", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Movilidad", "Barrio"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Geografía", "Ingeniería Civil", "Sociología", "Arquitectura", "Estadística", "Ingeniería Industrial", "Economía", "Trabajo Social"], "problema": ["Cada barrio tiene sus propias formas de moverse: algunos dependen del transporte público, otros caminan casi todo y otros usan moto o auto. Esa información casi nunca está escrita y, sin ella, es difícil saber qué mejoras se necesitan.", "Entender cómo se mueve la gente permite ver quién tiene más opciones y quién menos, y por qué."], "desarrollar": ["Diseña una encuesta anónima de cinco preguntas, como medio de transporte, destino, tiempo de viaje y motivo, y aplícala a una muestra pequeña de vecinos o compañeros que vivan en la misma zona.", "Resume los resultados en tablas y gráficos, identifica los destinos más frecuentes y describe qué grupos de personas tienen viajes más largos o menos opciones."], "ampliaciones": [{"titulo": "Por horas del día", "aporta": "compara cómo cambian los traslados entre la mañana, la tarde y la noche."}, {"titulo": "Por grupos", "aporta": "analiza si cambian según edad, ocupación o género."}, {"titulo": "Mapa de destinos", "aporta": "dibuja un mapa con los destinos más repetidos y sus rutas."}], "objetivos": ["Diseñar una encuesta anónima corta.", "Procesar y graficar respuestas.", "Identificar patrones de movilidad.", "Explicar diferencias entre grupos."], "habilidades": ["Diseño de encuestas.", "Estadística descriptiva.", "Lectura de datos de movilidad.", "Comunicación de resultados."], "herramientas": ["Un formulario anónimo.", "Hoja de cálculo.", "Un mapa en línea."], "lineamientos": ["La encuesta debe ser anónima y voluntaria; no pidas direcciones exactas, usa zonas o referencias generales.", "Presenta los resultados como tendencias de una muestra pequeña, no como verdades de todo el barrio."], "otroSector": "El mismo método sirve para estudiar cómo se mueven los estudiantes en un campus, los trabajadores de un parque industrial o los visitantes de un mercado."}$a1sld$::jsonb,17),
('mapa-de-rutas-de-transporte-publico-y-sus-conexiones-en-tu-zona','ciudades',array['tecnologia','sociedad']::text[],'Mapa de rutas de transporte público y sus conexiones en tu zona','Construye un mapa claro de las rutas de transporte público que pasan por tu zona, dónde se conectan entre sí y qué lugares quedan sin servicio cercano.','Prototipo','~22 h',22,array['Transporte público','Mapas']::text[],array['crear','investigar']::text[],'publicos',NULL,'ingenieria civil geografia ingenieria de sistemas ingenieria industrial arquitectura ciencia de datos estadistica economia cartografia basica. lectura de redes de transporte. observacion de campo. diseno de informacion. un mapa en linea editable. hoja de calculo. informacion publica de rutas autorizadas.',$a2sld${"id": "mapa-de-rutas-de-transporte-publico-y-sus-conexiones-en-tu-zona", "area": "ciudades", "areas2": ["tecnologia", "sociedad"], "titulo": "Mapa de rutas de transporte público y sus conexiones en tu zona", "resumen": "Construye un mapa claro de las rutas de transporte público que pasan por tu zona, dónde se conectan entre sí y qué lugares quedan sin servicio cercano.", "tipo": "Prototipo", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Transporte público", "Mapas"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Civil", "Geografía", "Ingeniería de Sistemas", "Ingeniería Industrial", "Arquitectura", "Ciencia de Datos", "Estadística", "Economía"], "problema": ["Las rutas de transporte existen, pero suelen estar dispersas en listas, paneles o en la memoria de quienes las usan. Para quien llega nuevo a una zona es difícil saber qué línea toma y dónde se conecta con otra.", "Un mapa claro de rutas y conexiones permite entender cómo funciona realmente el sistema en un lugar y dónde hay vacíos."], "desarrollar": ["Reúne con información pública y con observación las rutas que pasan por tu zona, con sus paraderos principales, y dibújalas en un mapa en línea o en un esquema.", "Marca los puntos donde se cruzan varias rutas, identifica zonas sin servicio a menos de diez minutos a pie y escribe una guía corta de cómo ir de tu zona a tres destinos importantes."], "ampliaciones": [{"titulo": "Esquema simplificado", "aporta": "crea un diagrama tipo plano de metro que simplifique las rutas."}, {"titulo": "Frecuencias", "aporta": "añade cada cuánto pasa cada ruta según tus observaciones."}, {"titulo": "Versión web", "aporta": "publica el mapa como una página sencilla con filtros por ruta."}], "objetivos": ["Reunir información pública de rutas.", "Representar rutas y conexiones.", "Identificar vacíos de cobertura.", "Explicar el mapa a nuevos usuarios."], "habilidades": ["Cartografía básica.", "Lectura de redes de transporte.", "Observación de campo.", "Diseño de información."], "herramientas": ["Un mapa en línea editable.", "Hoja de cálculo.", "Información pública de rutas autorizadas."], "lineamientos": ["Cita la fuente y la fecha de la información y avisa que las rutas pueden cambiar.", "No incluyas datos de conductores ni placas de vehículos."], "otroSector": "El mismo mapa sirve para rutas escolares, de recojo de residuos, de reparto de un negocio o de una ruta turística."}$a2sld$::jsonb,18),
('el-recorrido-mas-eficiente-entre-dos-puntos-de-la-ciudad','ciudades',array['negocios']::text[],'El recorrido más eficiente entre dos puntos de la ciudad','Compara varias formas de ir entre dos puntos de la ciudad según tiempo, costo, comodidad y cantidad de transbordos, y decide cuál es la más eficiente y para quién.','Análisis','~18 h',18,array['Rutas','Eficiencia']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria industrial ingenieria civil matematica ingenieria de sistemas geografia economia estadistica arquitectura medicion de procesos. analisis multicriterio. estadistica descriptiva. comunicacion de resultados. hoja de calculo. cronometro o aplicacion de notas. una aplicacion de mapas.',$a3sld${"id": "el-recorrido-mas-eficiente-entre-dos-puntos-de-la-ciudad", "area": "ciudades", "areas2": ["negocios"], "titulo": "El recorrido más eficiente entre dos puntos de la ciudad", "resumen": "Compara varias formas de ir entre dos puntos de la ciudad según tiempo, costo, comodidad y cantidad de transbordos, y decide cuál es la más eficiente y para quién.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Rutas", "Eficiencia"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Industrial", "Ingeniería Civil", "Matemática", "Ingeniería de Sistemas", "Geografía", "Economía", "Estadística", "Arquitectura"], "problema": ["El camino más corto en el mapa no siempre es el más rápido ni el más barato. Los transbordos, las esperas, el tráfico y la seguridad cambian el resultado.", "Comparar con datos propios ayuda a entender qué significa «eficiente» según las necesidades de cada persona."], "desarrollar": ["Elige dos puntos reales de tu ciudad y registra al menos tres maneras de ir de uno a otro, anotando tiempo total, costo, número de transbordos, esperas y comodidad, en dos momentos del día.", "Compara con una tabla, define criterios con pesos según el tipo de persona, como alguien con prisa, con poco dinero o con equipaje, y concluye qué ruta recomendarías en cada caso."], "ampliaciones": [{"titulo": "Con una aplicación de mapas", "aporta": "contrasta tus mediciones con lo que estima una aplicación."}, {"titulo": "Variabilidad", "aporta": "repite en varios días y mide cuánto cambia el tiempo real."}, {"titulo": "Ruta para alguien con movilidad reducida", "aporta": "analiza cuál sería la mejor ruta si hay escaleras o veredas rotas."}], "objetivos": ["Medir tiempos y costos reales.", "Comparar rutas con criterios claros.", "Considerar distintos tipos de usuarios.", "Justificar una recomendación."], "habilidades": ["Medición de procesos.", "Análisis multicriterio.", "Estadística descriptiva.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Cronómetro o aplicación de notas.", "Una aplicación de mapas."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "Registra solo tus propios viajes y no incluyas datos de otras personas."], "otroSector": "El mismo análisis sirve para rutas de reparto de un negocio, de recojo de residuos o de traslado de pacientes."}$a3sld$::jsonb,19),
('paraderos-y-puntos-de-acceso-al-transporte-donde-se-espera-demas','ciudades',array['sociedad']::text[],'Paraderos y puntos de acceso al transporte: ¿dónde se espera demasiado?','Mapea los paraderos y puntos de acceso al transporte de tu zona, mide cuánto se espera en cada uno y descubre dónde la espera es más larga o incómoda.','Análisis','~20 h',20,array['Paraderos','Tiempos de espera']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria civil ingenieria industrial geografia arquitectura estadistica sociologia ingenieria de sistemas matematica medicion en campo. estadistica descriptiva. evaluacion de infraestructura. propuestas de mejora. cronometro. hoja de calculo. una ficha de observacion.',$a4sld${"id": "paraderos-y-puntos-de-acceso-al-transporte-donde-se-espera-demas", "area": "ciudades", "areas2": ["sociedad"], "titulo": "Paraderos y puntos de acceso al transporte: ¿dónde se espera demasiado?", "resumen": "Mapea los paraderos y puntos de acceso al transporte de tu zona, mide cuánto se espera en cada uno y descubre dónde la espera es más larga o incómoda.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Paraderos", "Tiempos de espera"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Ingeniería Industrial", "Geografía", "Arquitectura", "Estadística", "Sociología", "Ingeniería de Sistemas", "Matemática"], "problema": ["Un paradero no es solo un poste con un cartel: puede tener techo, sombra, asientos, buena iluminación y espacio para esperar con seguridad, o puede no tener nada. La espera también varía según el lugar y la hora.", "Medirla permite saber dónde se pierde más tiempo y qué mejoras serían más útiles."], "desarrollar": ["Elige cinco paraderos o puntos de acceso, registra en dos horarios cuánto tiempo pasa entre un vehículo y otro, cuántas personas esperan y qué condiciones tiene el lugar, como techo, asientos, luz y espacio.", "Calcula la espera promedio y la máxima, califica cada punto con un puntaje de condiciones y propón mejoras concretas para los dos puntos con peores resultados."], "ampliaciones": [{"titulo": "Espera frente a espera percibida", "aporta": "pregunta a quienes esperan cuánto sienten que esperaron y compara."}, {"titulo": "Seguridad", "aporta": "añade cómo se siente la gente de noche en cada punto."}, {"titulo": "Costo de una mejora", "aporta": "estima cuánto costaría techar o iluminar un paradero."}], "objetivos": ["Medir esperas con método.", "Evaluar condiciones de cada punto.", "Comparar puntos entre sí.", "Proponer mejoras concretas."], "habilidades": ["Medición en campo.", "Estadística descriptiva.", "Evaluación de infraestructura.", "Propuestas de mejora."], "herramientas": ["Cronómetro.", "Hoja de cálculo.", "Una ficha de observación."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo método sirve para medir esperas en ventanillas, ascensores, comedores o centros de atención."}$a4sld$::jsonb,20),
('que-tan-accesible-es-tu-universidad-en-transporte-publico','ciudades',array['educacion','sociedad']::text[],'¿Qué tan accesible es tu universidad en transporte público?','Mide cuánto tiempo, dinero y esfuerzo cuesta llegar a tu universidad en transporte público desde distintos puntos de la ciudad.','Análisis','~20 h',20,array['Acceso','Universidad']::text[],array['investigar']::text[],'propios',NULL,'ingenieria civil geografia ingenieria industrial sociologia economia estadistica ingenieria de sistemas educacion analisis de accesibilidad. cartografia basica. calculo de costos. interpretacion de resultados. una aplicacion de mapas. hoja de calculo. tarifas publicas de transporte.',$a5sld${"id": "que-tan-accesible-es-tu-universidad-en-transporte-publico", "area": "ciudades", "areas2": ["educacion", "sociedad"], "titulo": "¿Qué tan accesible es tu universidad en transporte público?", "resumen": "Mide cuánto tiempo, dinero y esfuerzo cuesta llegar a tu universidad en transporte público desde distintos puntos de la ciudad.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Acceso", "Universidad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Geografía", "Ingeniería Industrial", "Sociología", "Economía", "Estadística", "Ingeniería de Sistemas", "Educación"], "problema": ["La ubicación de una universidad determina quién puede llegar a ella con facilidad. Para algunos estudiantes el viaje toma poco; para otros son horas y varios transbordos, lo que afecta el cansancio, la puntualidad y el gasto.", "Medirlo sirve para ver qué zonas quedan lejos en la práctica, no solo en kilómetros."], "desarrollar": ["Elige entre cinco y ocho puntos de partida repartidos por la ciudad y averigua para cada uno el tiempo, el costo y el número de transbordos para llegar a tu universidad en hora punta, con aplicaciones de mapas y tarifas públicas.", "Presenta los resultados en un mapa de colores por tiempo de viaje y concluye qué zonas están mejor o peor conectadas y qué cambios mejorarían el acceso."], "ampliaciones": [{"titulo": "Costo mensual", "aporta": "calcula cuánto gasta un estudiante en pasajes al mes desde cada zona."}, {"titulo": "Horarios nocturnos", "aporta": "analiza cómo cambia el acceso para quienes salen de noche."}, {"titulo": "Propuesta de mejora", "aporta": "propón una ruta o un horario que reduzca el viaje desde la zona peor conectada."}], "objetivos": ["Medir tiempo y costo de acceso.", "Comparar zonas de origen.", "Representar la información en un mapa.", "Proponer mejoras."], "habilidades": ["Análisis de accesibilidad.", "Cartografía básica.", "Cálculo de costos.", "Interpretación de resultados."], "herramientas": ["Una aplicación de mapas.", "Hoja de cálculo.", "Tarifas públicas de transporte."], "lineamientos": ["Usa zonas o distritos y no direcciones de personas; las estimaciones de una aplicación no sustituyen la experiencia real del viaje.", "Indica la fecha y la hora de cada medición."], "otroSector": "El mismo análisis sirve para evaluar el acceso a un hospital, un mercado, un colegio o un centro de trabajo."}$a5sld$::jsonb,21),
('que-tan-conectados-estan-los-barrios-con-los-principales-servici','ciudades',array['sociedad']::text[],'¿Qué tan conectados están los barrios con los principales servicios de la ciudad?','Compara cuánto tardan los habitantes de distintos barrios en llegar a hospitales, mercados, colegios y oficinas públicas, y descubre qué zonas quedan más aisladas.','Análisis','~22 h',22,array['Conectividad','Servicios']::text[],array['investigar']::text[],'publicos',NULL,'geografia ingenieria civil sociologia economia estadistica ciencia de datos arquitectura trabajo social analisis espacial basico. busqueda de datos publicos. comparacion y puntuacion. comunicacion de resultados. un mapa en linea. hoja de calculo. portales de datos abiertos.',$a6sld${"id": "que-tan-conectados-estan-los-barrios-con-los-principales-servici", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Qué tan conectados están los barrios con los principales servicios de la ciudad?", "resumen": "Compara cuánto tardan los habitantes de distintos barrios en llegar a hospitales, mercados, colegios y oficinas públicas, y descubre qué zonas quedan más aisladas.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Conectividad", "Servicios"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Geografía", "Ingeniería Civil", "Sociología", "Economía", "Estadística", "Ciencia de Datos", "Arquitectura", "Trabajo Social"], "problema": ["No todos los barrios están igual de cerca de los servicios importantes. Vivir lejos de un hospital, un mercado o una oficina pública significa más tiempo, más gasto y más dificultad.", "Esa distancia casi nunca se mide, y por eso es difícil decidir dónde conviene mejorar el transporte o instalar un servicio."], "desarrollar": ["Elige cuatro barrios y cinco tipos de servicios, ubica con datos públicos los más cercanos a cada barrio y estima el tiempo de viaje y el costo con aplicaciones de mapas.", "Arma una tabla comparativa, puntúa cada barrio y explica qué zonas están más aisladas y qué servicio sería el más importante de acercar."], "ampliaciones": [{"titulo": "Servicio crítico", "aporta": "analiza solo servicios de emergencia, como salud o bomberos."}, {"titulo": "Barrio frente a su vecino", "aporta": "explica por qué dos barrios cercanos tienen accesos tan distintos."}, {"titulo": "Propuesta de ubicación", "aporta": "sugiere dónde ubicar un nuevo servicio para reducir las distancias."}], "objetivos": ["Ubicar servicios con datos públicos.", "Calcular tiempos de acceso.", "Comparar barrios.", "Priorizar mejoras con argumentos."], "habilidades": ["Análisis espacial básico.", "Búsqueda de datos públicos.", "Comparación y puntuación.", "Comunicación de resultados."], "herramientas": ["Un mapa en línea.", "Hoja de cálculo.", "Portales de datos abiertos."], "lineamientos": ["Usa información pública y fecha tus datos; evita describir a un barrio con etiquetas negativas, limítate a lo medido.", "Los tiempos son estimaciones y cambian con el tráfico."], "otroSector": "El mismo análisis sirve para estudiar el acceso a servicios en una región rural, una provincia o un campus."}$a6sld$::jsonb,22),
('que-tan-facil-es-combinar-diferentes-medios-de-transporte-para-l','ciudades',array['sociedad']::text[],'¿Qué tan fácil es combinar diferentes medios de transporte para llegar a un destino?','Evalúa qué tan cómodo es pasar de un medio de transporte a otro, como del bus a un tren o a una bici, midiendo distancias, esperas, señalización y costos de cada cambio.','Análisis','~18 h',18,array['Intermodalidad','Transporte']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria civil ingenieria industrial geografia arquitectura economia sociologia ingenieria de sistemas estadistica evaluacion en campo. diseno de fichas de criterios. analisis comparativo. propuesta de soluciones. una ficha de observacion. cronometro. una aplicacion de mapas.',$a7sld${"id": "que-tan-facil-es-combinar-diferentes-medios-de-transporte-para-l", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Qué tan fácil es combinar diferentes medios de transporte para llegar a un destino?", "resumen": "Evalúa qué tan cómodo es pasar de un medio de transporte a otro, como del bus a un tren o a una bici, midiendo distancias, esperas, señalización y costos de cada cambio.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Intermodalidad", "Transporte"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Ingeniería Industrial", "Geografía", "Arquitectura", "Economía", "Sociología", "Ingeniería de Sistemas", "Estadística"], "problema": ["Muchos viajes combinan varios medios, y es en los cambios donde se pierde más tiempo y comodidad: caminatas largas entre estaciones, falta de información, cobros duplicados o puntos inseguros.", "Un sistema puede tener buenas rutas y aun así ser incómodo si los transbordos están mal resueltos."], "desarrollar": ["Elige dos o tres puntos donde se combinan medios de transporte y recorre el transbordo anotando distancia, tiempo, señalización, protección del clima, seguridad y costo de cada cambio.", "Califica cada punto con una ficha de criterios, compara los resultados y propón tres mejoras prácticas para el punto con peor calificación."], "ampliaciones": [{"titulo": "Para personas con movilidad reducida", "aporta": "evalúa si el transbordo es posible con silla de ruedas o con coche de bebé."}, {"titulo": "Información al usuario", "aporta": "analiza si los carteles y mapas permiten encontrar el siguiente medio sin preguntar."}, {"titulo": "Costo integrado", "aporta": "calcula cuánto se ahorraría con un pasaje único para el viaje combinado."}], "objetivos": ["Evaluar puntos de transbordo.", "Medir tiempos y distancias.", "Calificar con criterios claros.", "Proponer mejoras."], "habilidades": ["Evaluación en campo.", "Diseño de fichas de criterios.", "Análisis comparativo.", "Propuesta de soluciones."], "herramientas": ["Una ficha de observación.", "Cronómetro.", "Una aplicación de mapas."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo método sirve para evaluar cambios entre sistemas de salud, entre aplicaciones o entre procesos de una empresa."}$a7sld$::jsonb,23),
('cuanto-tiempo-pierde-una-persona-al-trasladarse-diariamente-por','ciudades',array['negocios','salud']::text[],'¿Cuánto tiempo pierde una persona al trasladarse diariamente por su ciudad?','Mide cuánto tiempo pasan las personas en traslados cada día y cuánto de ese tiempo es viaje útil y cuánto es espera, tráfico o caminata, para ver qué parte se podría reducir.','Análisis','~18 h',18,array['Tiempo','Movilidad']::text[],array['investigar']::text[],'propios',NULL,'economia ingenieria industrial ingenieria civil estadistica sociologia psicologia geografia administracion registro de tiempos. estadistica descriptiva. analisis de procesos. comunicacion de resultados. hoja de calculo. cronometro o aplicacion de notas. un editor de graficos.',$a8sld${"id": "cuanto-tiempo-pierde-una-persona-al-trasladarse-diariamente-por", "area": "ciudades", "areas2": ["negocios", "salud"], "titulo": "¿Cuánto tiempo pierde una persona al trasladarse diariamente por su ciudad?", "resumen": "Mide cuánto tiempo pasan las personas en traslados cada día y cuánto de ese tiempo es viaje útil y cuánto es espera, tráfico o caminata, para ver qué parte se podría reducir.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Tiempo", "Movilidad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Ingeniería Industrial", "Ingeniería Civil", "Estadística", "Sociología", "Psicología", "Geografía", "Administración"], "problema": ["Para muchas personas, ir y volver de estudiar o trabajar consume varias horas al día. Ese tiempo no se ve en ningún presupuesto, pero afecta el descanso, el estudio y la vida social.", "Separar el tiempo de viaje del tiempo de espera y de caminata permite ver dónde está realmente la pérdida."], "desarrollar": ["Durante una semana anota tus traslados, o los de un caso ficticio, dividiendo cada uno en caminata, espera, viaje y transbordo, con la hora y el medio de transporte.", "Calcula el tiempo semanal y anual en cada parte, compara con el de dos compañeros que lo hagan de forma anónima y propón qué cambios reducirían más el tiempo perdido."], "ampliaciones": [{"titulo": "Convertirlo en horas de vida", "aporta": "calcula cuántas horas al año se dedican a trasladarse."}, {"titulo": "Qué se hace en el viaje", "aporta": "analiza qué actividades útiles se podrían hacer durante el viaje."}, {"titulo": "Horarios flexibles", "aporta": "evalúa cuánto se reduciría el tiempo si se viaja fuera de hora punta."}], "objetivos": ["Registrar traslados con método.", "Separar tiempos de caminata, espera y viaje.", "Comparar casos.", "Identificar cambios con mayor efecto."], "habilidades": ["Registro de tiempos.", "Estadística descriptiva.", "Análisis de procesos.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Cronómetro o aplicación de notas.", "Un editor de gráficos."], "lineamientos": ["Usa tus datos o casos ficticios; si comparas con otros, que sea de forma anónima y voluntaria.", "No lo uses para criticar las decisiones de dónde vive o trabaja cada persona."], "otroSector": "El mismo análisis sirve para medir tiempos en un hospital, en una cocina, en un trámite o en una línea de producción."}$a8sld$::jsonb,24),
('propuesta-para-mejorar-los-recorridos-peatonales-hacia-una-estac','ciudades',array['sociedad']::text[],'Propuesta para mejorar los recorridos peatonales hacia una estación de transporte','Diagnostica el camino que recorre la gente a pie hasta una estación o paradero importante y diseña mejoras de seguridad, sombra, señalización y continuidad.','Plan','~25 h',25,array['Peatones','Diseño urbano']::text[],array['crear','resolver']::text[],'propios',NULL,'arquitectura ingenieria civil geografia diseno sociologia ingenieria industrial ingenieria ambiental economia observacion de campo. diseno urbano basico. dibujo de propuestas. estimacion de costos. una ficha de observacion. un programa de dibujo o planos. hoja de calculo.',$a9sld${"id": "propuesta-para-mejorar-los-recorridos-peatonales-hacia-una-estac", "area": "ciudades", "areas2": ["sociedad"], "titulo": "Propuesta para mejorar los recorridos peatonales hacia una estación de transporte", "resumen": "Diagnostica el camino que recorre la gente a pie hasta una estación o paradero importante y diseña mejoras de seguridad, sombra, señalización y continuidad.", "tipo": "Plan", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Peatones", "Diseño urbano"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Geografía", "Diseño", "Sociología", "Ingeniería Industrial", "Ingeniería Ambiental", "Economía"], "problema": ["Casi todos los viajes en transporte público empiezan y terminan caminando. Si el camino a la estación es inseguro, caluroso, está roto o sin luz, el sistema entero se siente peor.", "Mejorar esos últimos metros suele ser más barato que cambiar la ruta y tiene un efecto directo en quien camina."], "desarrollar": ["Elige una estación o paradero y recorre los cuatro accesos principales, anotando cuántos metros hay, qué tiene la vereda, cómo son los cruces, la iluminación, la sombra y los obstáculos.", "Califica cada recorrido, identifica los tres problemas más graves y dibuja una propuesta de mejora con medidas concretas y una estimación del costo de cada una."], "ampliaciones": [{"titulo": "Voz de quienes caminan", "aporta": "entrevista a cinco usuarios sobre qué cambiarían."}, {"titulo": "Antes y después", "aporta": "dibuja cómo se vería el recorrido con las mejoras."}, {"titulo": "Prioridades", "aporta": "ordena las mejoras por costo y por efecto para proponer una primera etapa."}], "objetivos": ["Diagnosticar un recorrido peatonal.", "Evaluar condiciones con criterios.", "Diseñar mejoras concretas.", "Estimar costos y prioridades."], "habilidades": ["Observación de campo.", "Diseño urbano básico.", "Dibujo de propuestas.", "Estimación de costos."], "herramientas": ["Una ficha de observación.", "Un programa de dibujo o planos.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen.", "Presenta tu propuesta como una sugerencia y no como una crítica a las autoridades."], "otroSector": "El mismo método sirve para mejorar el acceso a un colegio, un mercado, un hospital o un parque."}$a9sld$::jsonb,25),
('conectividad-peatonal-de-una-zona-se-puede-caminar-de-un-lugar-a','ciudades',array['sociedad']::text[],'Conectividad peatonal de una zona: ¿se puede caminar de un lugar a otro?','Evalúa si las veredas, cruces y pasajes de una zona forman una red continua para caminar o si hay cortes, rodeos y lugares que quedan aislados.','Análisis','~20 h',20,array['Caminabilidad','Redes']::text[],array['investigar']::text[],'propios',NULL,'geografia arquitectura ingenieria civil matematica ciencia de datos sociologia ingenieria de sistemas estadistica analisis espacial. medicion en campo. representacion en redes. propuestas de mejora. un mapa en linea. hoja de calculo. opcionalmente, python para analizar redes.',$a10sld${"id": "conectividad-peatonal-de-una-zona-se-puede-caminar-de-un-lugar-a", "area": "ciudades", "areas2": ["sociedad"], "titulo": "Conectividad peatonal de una zona: ¿se puede caminar de un lugar a otro?", "resumen": "Evalúa si las veredas, cruces y pasajes de una zona forman una red continua para caminar o si hay cortes, rodeos y lugares que quedan aislados.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Caminabilidad", "Redes"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Geografía", "Arquitectura", "Ingeniería Civil", "Matemática", "Ciencia de Datos", "Sociología", "Ingeniería de Sistemas", "Estadística"], "problema": ["Una zona puede tener veredas y aun así no ser fácil de caminar si hay tramos cortados, cruces peligrosos o avenidas que dividen el barrio. Un camino que parece corto en el mapa puede exigir un rodeo largo.", "Mirar la zona como una red permite ver qué conexiones faltan y cuáles darían más beneficio."], "desarrollar": ["Elige una zona pequeña con varios puntos de interés, como colegio, mercado, paradero y parque, dibuja las veredas y cruces existentes y mide la distancia a pie real entre los puntos.", "Compara esa distancia con la distancia en línea recta, identifica dónde hay rodeos excesivos o cortes y propón dos conexiones nuevas que reducirían más el camino."], "ampliaciones": [{"titulo": "Índice de rodeo", "aporta": "calcula un indicador de cuánto más se camina que en línea recta."}, {"titulo": "Puntos aislados", "aporta": "identifica lugares a los que casi no se puede llegar a pie."}, {"titulo": "Red como grafo", "aporta": "representa la zona como una red con nodos y conexiones y analízala con un programa."}], "objetivos": ["Representar una red peatonal.", "Medir distancias reales.", "Detectar cortes y rodeos.", "Proponer nuevas conexiones."], "habilidades": ["Análisis espacial.", "Medición en campo.", "Representación en redes.", "Propuestas de mejora."], "herramientas": ["Un mapa en línea.", "Hoja de cálculo.", "Opcionalmente, Python para analizar redes."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "Anota solo características físicas del espacio, no datos de las viviendas ni de las personas."], "otroSector": "El mismo análisis de redes sirve para estudiar conexiones entre aulas de un campus, caminos rurales o rutas dentro de un hospital."}$a10sld$::jsonb,26),
('diagnostico-de-seguridad-vial-alrededor-de-una-institucion-educa','ciudades',array['educacion','salud']::text[],'Diagnóstico de seguridad vial alrededor de una institución educativa','Evalúa qué tan seguro es el entorno vial de un colegio o universidad: cruces, velocidad de los vehículos, señales, veredas y horas de mayor riesgo.','Análisis','~22 h',22,array['Seguridad vial','Colegios']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria civil arquitectura ingenieria industrial sociologia educacion psicologia estadistica ingenieria ambiental observacion sistematica. diagnostico de infraestructura. priorizacion. redaccion tecnica. una ficha de observacion. un mapa en linea. hoja de calculo.',$a11sld${"id": "diagnostico-de-seguridad-vial-alrededor-de-una-institucion-educa", "area": "ciudades", "areas2": ["educacion", "salud"], "titulo": "Diagnóstico de seguridad vial alrededor de una institución educativa", "resumen": "Evalúa qué tan seguro es el entorno vial de un colegio o universidad: cruces, velocidad de los vehículos, señales, veredas y horas de mayor riesgo.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Seguridad vial", "Colegios"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Arquitectura", "Ingeniería Industrial", "Sociología", "Educación", "Psicología", "Estadística", "Ingeniería Ambiental"], "problema": ["En la entrada y la salida de una institución educativa coinciden muchas personas, vehículos de recojo y transporte público. Esos momentos concentran riesgos para peatones, especialmente niños y jóvenes.", "Un diagnóstico ordenado permite señalar qué problemas son más graves y cuáles son más fáciles de corregir."], "desarrollar": ["Recorre el entorno de una institución y completa una ficha con aspectos como veredas, cruces, señales, semáforos, estacionamientos informales, iluminación y espacios de espera.", "Observa la entrada y la salida durante varios días anotando situaciones de riesgo, resume los hallazgos en un mapa de puntos críticos y propón cinco medidas priorizadas."], "ampliaciones": [{"titulo": "Velocidad de los vehículos", "aporta": "estima con una referencia simple qué tan rápido pasan los vehículos."}, {"titulo": "Voz de la comunidad", "aporta": "pregunta a estudiantes y padres qué lugares consideran más peligrosos."}, {"titulo": "Plan de mejora", "aporta": "diseña un plan escalonado con responsables posibles."}], "objetivos": ["Aplicar una ficha de diagnóstico.", "Identificar puntos críticos.", "Priorizar medidas.", "Comunicar resultados con claridad."], "habilidades": ["Observación sistemática.", "Diagnóstico de infraestructura.", "Priorización.", "Redacción técnica."], "herramientas": ["Una ficha de observación.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen.", "Si el entorno es de un colegio, pide permiso a la dirección antes de observar y no incluyas imágenes de menores."], "otroSector": "El mismo diagnóstico sirve para entornos de hospitales, mercados, terminales y centros comerciales."}$a11sld$::jsonb,27),
('son-visibles-y-suficientes-las-senales-de-transito-de-tu-zona','ciudades',array['sociedad']::text[],'¿Son visibles y suficientes las señales de tránsito de tu zona?','Revisa si las señales de tránsito de una zona están donde deben, se ven bien, están en buen estado y se entienden, y qué señales faltan.','Análisis','~15 h',15,array['Señalización','Tránsito']::text[],array['investigar']::text[],'propios',NULL,'ingenieria civil ingenieria industrial arquitectura diseno derecho ingenieria de sistemas estadistica psicologia inventario en campo. evaluacion de visibilidad. lectura de normas. propuesta de mejoras. una ficha de inventario. un mapa en linea. el manual oficial de senales.',$a12sld${"id": "son-visibles-y-suficientes-las-senales-de-transito-de-tu-zona", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Son visibles y suficientes las señales de tránsito de tu zona?", "resumen": "Revisa si las señales de tránsito de una zona están donde deben, se ven bien, están en buen estado y se entienden, y qué señales faltan.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Señalización", "Tránsito"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Ingeniería Industrial", "Arquitectura", "Diseño", "Derecho", "Ingeniería de Sistemas", "Estadística", "Psicología"], "problema": ["Una señal que no se ve, está rota, tapada por un árbol o mal ubicada no cumple su función. Muchos accidentes y confusiones pasan porque las señales no están donde la gente las necesita.", "Un inventario sencillo permite saber qué hay, en qué estado está y dónde hacen falta más."], "desarrollar": ["Recorre varias cuadras y crea un inventario de las señales que encuentres, con su tipo, ubicación, visibilidad, estado y si su mensaje se entiende a simple vista.", "Marca en un mapa los lugares con señales faltantes o en mal estado, compara de día y de noche y propón mejoras de ubicación o de diseño."], "ampliaciones": [{"titulo": "Lo que entiende la gente", "aporta": "pregunta a diez personas qué significan algunas señales y cuántas aciertan."}, {"titulo": "Señalización para peatones", "aporta": "revisa si hay señales para quien camina y no solo para quien conduce."}, {"titulo": "Normativa", "aporta": "compara lo que encuentras con las normas oficiales de señalización."}], "objetivos": ["Crear un inventario de señales.", "Evaluar visibilidad y estado.", "Detectar vacíos.", "Proponer mejoras."], "habilidades": ["Inventario en campo.", "Evaluación de visibilidad.", "Lectura de normas.", "Propuesta de mejoras."], "herramientas": ["Una ficha de inventario.", "Un mapa en línea.", "El manual oficial de señales."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "Describe los problemas de forma objetiva, sin atribuir culpas a personas o instituciones concretas."], "otroSector": "El mismo inventario sirve para señalización de evacuación, de un hospital, de un campus o de un museo."}$a12sld$::jsonb,28),
('analisis-de-rutas-escolares-seguras','ciudades',array['educacion','sociedad']::text[],'Análisis de rutas escolares seguras','Analiza los caminos que usan niños y jóvenes para llegar a un colegio, identifica los tramos riesgosos y propone una ruta más segura con puntos de apoyo.','Plan','~22 h',22,array['Rutas escolares','Seguridad']::text[],array['resolver','crear']::text[],'propios',NULL,'ingenieria civil educacion psicologia sociologia arquitectura trabajo social geografia ingenieria industrial observacion de campo. evaluacion de riesgos. cartografia basica. comunicacion clara. un mapa en linea. una ficha de calificacion. un editor de infografias.',$a13sld${"id": "analisis-de-rutas-escolares-seguras", "area": "ciudades", "areas2": ["educacion", "sociedad"], "titulo": "Análisis de rutas escolares seguras", "resumen": "Analiza los caminos que usan niños y jóvenes para llegar a un colegio, identifica los tramos riesgosos y propone una ruta más segura con puntos de apoyo.", "tipo": "Plan", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Rutas escolares", "Seguridad"], "intencion": ["resolver", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Educación", "Psicología", "Sociología", "Arquitectura", "Trabajo Social", "Geografía", "Ingeniería Industrial"], "problema": ["Muchos estudiantes llegan a pie o en transporte público por caminos que nadie ha evaluado. Cruces sin semáforo, veredas rotas, tramos oscuros o poca presencia de adultos pueden ser un riesgo.", "Identificar una ruta segura y señalar los puntos críticos ayuda a las familias y a la institución a tomar decisiones."], "desarrollar": ["Con un colegio real, con permiso, o uno ficticio, dibuja las rutas más usadas por los estudiantes, recorre cada una en horario de entrada y salida y califica cada tramo según veredas, cruces, iluminación y presencia de personas.", "Construye un mapa con la ruta recomendada y los puntos críticos, y escribe una guía de recomendaciones para estudiantes, familias y la institución."], "ampliaciones": [{"titulo": "Voz de los estudiantes", "aporta": "pregunta de forma anónima qué tramos los hacen sentir inseguros."}, {"titulo": "Hora de salida", "aporta": "compara la seguridad de la ruta entre la entrada y la salida."}, {"titulo": "Aliados del camino", "aporta": "identifica negocios o puntos de apoyo que podrían ofrecer ayuda."}], "objetivos": ["Mapear rutas escolares.", "Evaluar tramos con criterios.", "Elaborar una ruta recomendada.", "Comunicar recomendaciones a distintos públicos."], "habilidades": ["Observación de campo.", "Evaluación de riesgos.", "Cartografía básica.", "Comunicación clara."], "herramientas": ["Un mapa en línea.", "Una ficha de calificación.", "Un editor de infografías."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No incluyas nombres, fotos ni horarios exactos de menores; trabaja con zonas y tramos, no con personas.", "Pide autorización a la institución y a las familias si hay participación de menores."], "otroSector": "El mismo método sirve para rutas de adultos mayores, de personas que trabajan de noche o de visitantes de un evento."}$a13sld$::jsonb,29)
